def safe_path(text):
    if text.startswith('/') or '\\' in text or '\x00' in text: raise ValueError('path')
    parts=[p for p in text.split('/') if p not in ('','.')] 
    if not parts or '..' in parts: raise ValueError('path')
    return '/'.join(parts)

