import unittest
from solution import safe_path

class ContractTests(unittest.TestCase):
    def test_00(self):
        self.assertEqual(safe_path('a//./b'),'a/b')
    def test_01(self):
        with self.assertRaises(ValueError): safe_path('a/../b')
    def test_02(self):
        with self.assertRaises(ValueError): safe_path('/tmp/a')
    def test_03(self):
        with self.assertRaises(ValueError): safe_path('a\\b')

